#include <iostream>
using namespace std;

// Iterative Binary Search
int binarySearch(int arr[], int n, int target) {
    int low = 0, high = n - 1;

    while(low <= high) {
        int mid = low + (high - low) / 2;  // Overflow se bachne ke liye

        if(arr[mid] == target) return mid;
        else if(arr[mid] < target) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

// Recursive Binary Search
int binarySearchRec(int arr[], int low, int high, int target) {
    if(low > high) return -1;

    int mid = low + (high - low) / 2;

    if(arr[mid] == target) return mid;
    else if(arr[mid] < target) return binarySearchRec(arr, mid + 1, high, target);
    else return binarySearchRec(arr, low, mid - 1, target);
}

int main() {
    int arr[] = {2, 5, 8, 12, 16, 23, 38, 45};
    int n = 8;
    cout << "Iterative: " << binarySearch(arr, n, 23) << endl;     // 5
    cout << "Recursive: " << binarySearchRec(arr, 0, n-1, 23) << endl; // 5
    return 0;
}

