#include <iostream>
#include <vector>
using namespace std;

// Staircase Search - Row & Column wise sorted matrix
bool searchMatrix(vector<vector<int>>& matrix, int target) {
    int rows = matrix.size(), cols = matrix[0].size();
    int row = 0, col = cols - 1;  // Start from top-right

    while(row < rows && col >= 0) {
        if(matrix[row][col] == target) return true;
        else if(matrix[row][col] > target) col--;  // Move left
        else row++;  // Move down
    }
    return false;
}

// Binary Search - Fully sorted matrix (each row starts after prev row ends)
bool searchMatrixBS(vector<vector<int>>& matrix, int target) {
    int rows = matrix.size(), cols = matrix[0].size();
    int low = 0, high = rows * cols - 1;

    while(low <= high) {
        int mid = low + (high - low) / 2;
        int element = matrix[mid / cols][mid % cols];

        if(element == target) return true;
        else if(element < target) low = mid + 1;
        else high = mid - 1;
    }
    return false;
}

int main() {
    vector<vector<int>> matrix = {
        {1,  4,  7,  11},
        {2,  5,  8,  12},
        {3,  6,  9,  16},
        {10, 13, 14, 17}
    };
    cout << "Found 5: " << (searchMatrix(matrix, 5) ? "Yes" : "No") << endl;
    cout << "Found 15: " << (searchMatrix(matrix, 15) ? "Yes" : "No") << endl;
    return 0;
}

